#!/bin/bash
# Print the three most frequent IPs in access.log, most frequent first,
# ties broken by first appearance in the log.
awk '{
    ip = $1
    if (!(ip in count)) first[ip] = NR
    count[ip]++
}
END {
    for (ip in count)
        printf "%d\t%d\t%s\n", count[ip], first[ip], ip
}' access.log | sort -t$'\t' -k1,1nr -k2,2n | head -n 3 | cut -f3
